select * from (
    select a.*,b.machine_name
    from t_lh_specify_machine a left join t_lh_machine_info b on a.machine_code=b.machine_code

        a.del_flag='0'
        and INSTR(a.sap_code, #{sapCode}) > 0
        and a.machine_code = #{machineCode}
        and a.line_type = #{lineType}
        and a.job_type = #{jobType}


        order by a.create_time desc

)t

    order by ${orderStr}

